# Test with reflection-based symmetry instead of rotation
Q1 = [
    [3, 3, 1, 3, 3],
    [6, 3, 3, 5, 6],
    [1, 5, 3, 3, 3],
    [5, 3, 6, 3, 0],
    [3, 3, 5, 3, 3]
]

# Horizontal flip (left-right mirror)
def flip_h(grid):
    return [[row[::-1] for row in grid]]

# Vertical flip (up-down mirror)  
def flip_v(grid):
    return [list(row)[::-1] for row in grid[::-1]]

hflipped = flip_h(Q1)
vflipped = flip_v(Q1)

print("Horizontal flip of Q1:")
for row in hflipped[0]: print(row)

print("\nVertical flip of Q1:")
for row in vflipped: print(row)

# Now construct full grid with horizontal reflection
result = [[0]*11 for _ in range(11)]
divider_row = 5
divider_col = 5

# Set dividers
for c in range(11):
    result[divider_row][c] = 4
for r in range(11):
    result[r][divider_col] = 4

# Fill TL from Q1
for r in range(5):
    for c in range(5):
        result[r][c] = Q1[r][c]

# Fill TR = horizontal flip of TL
for r in range(5):
    for c in range(6, 11):
        # col_local = c - 6 (0-4), but we want mirrored value
        # original Q1[r][4-col_local] = Q1[r][4-(c-6)] = Q1[r][10-c]
        result[r][c] = Q1[r][10-c]

# Fill BL = vertical flip of TL
for r in range(6, 11):
    for c in range(5):
        # row_local = r - 6, map to Q1[4-row_local]
        result[r][c] = Q1[10-r][c]

# Fill BR = both flips = vertical then horizontal
for r in range(6, 11):
    for c in range(6, 11):
        result[r][c] = Q1[10-r][10-c]

print("\nGrid with H-reflection symmetry:")
for row in result:
    print([str(x) for x in row])

